import Foundation
import Testing
@testable import StillfailHelper

@Test
func aClipboardsMarkIsTheStrictestOfItsTypes() {
  #expect(Clipboard.mark(of: ["public.utf8-plain-text"]) == 0)
  #expect(Clipboard.mark(of: ["public.utf8-plain-text", "org.nspasteboard.ConcealedType"]) == 1)
  #expect(Clipboard.mark(of: ["com.agilebits.onepassword"]) == 1)
  #expect(Clipboard.mark(of: ["de.petermaurer.TransientPasteboardType"]) == 2)
  #expect(Clipboard.mark(of: ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType"]) == 2)
  #expect(Clipboard.mark(of: ["org.nspasteboard.AutoGeneratedType", "org.nspasteboard.ConcealedType"]) == 1)
  #expect(Clipboard.mark(of: ["com.typeit4me.clipping"]) == 3)
  #expect(Clipboard.mark(of: ["Pasteboard generator type"]) == 3)
}

@Test
func aMarkIsWrittenAsItsOwnType() {
  #expect(Clipboard.type(of: 0) == nil)
  #expect(Clipboard.type(of: 1) == "org.nspasteboard.ConcealedType")
  #expect(Clipboard.type(of: 2) == "org.nspasteboard.TransientType")
  #expect(Clipboard.type(of: 3) == "org.nspasteboard.AutoGeneratedType")
}

@Test
func aSetsFlagsSayPasteAndTheMark() {
  #expect(Clipboard.flags(0) == (false, 0))
  #expect(Clipboard.flags(1) == (true, 0))
  #expect(Clipboard.flags(1 | (1 << 1)) == (true, 1))
  #expect(Clipboard.flags(2 << 1) == (false, 2))
  #expect(Clipboard.flags(0xff) == (true, 3))
}

@Test
func lockScreenTextPasteTypesDirectlyWithoutUsingClipboard() {
  let body = Data("s3cr3t!".utf8)
  #expect(Clipboard.lockedPasteText(paste: true, type: 1, body: body, locked: true) == "s3cr3t!")
  #expect(Clipboard.lockedPasteText(paste: true, type: 1, body: body, locked: false) == nil)
  #expect(Clipboard.lockedPasteText(paste: false, type: 1, body: body, locked: true) == nil)
  #expect(Clipboard.lockedPasteText(paste: true, type: 2, body: body, locked: true) == nil)
  #expect(Clipboard.lockedPasteText(paste: true, type: 1, body: Data([0xff, 0xfe]), locked: true) == nil)
}

@Test
func lockScreenTextChunksAreOneCharacterPerEventWithoutNewlines() {
  let chunks = ScreenInput.lockedTextChunks("aB1!\r\n🔑x\n")
  let decoded = chunks.map { String(utf16CodeUnits: $0, count: $0.count) }
  #expect(decoded == ["a", "B", "1", "!", "🔑", "x"])
  #expect(chunks[4].count == 2)
}
